"""Freeze a developmental model comparison before its responses exist."""
import datetime,hashlib,json,pathlib,random,subprocess
ROOT=pathlib.Path(__file__).resolve().parent
if (ROOT/'pilot/manifest.json').exists():
 raise RuntimeError('This pilot is already frozen. Create a new pilot namespace; never overwrite the original manifest or allocations.')
def dump(p,v):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(v,indent=2)+'\n')
def sha(p):return 'sha256:'+hashlib.sha256(p.read_bytes()).hexdigest()
repo=json.loads((ROOT.parent/'work/repository.json').read_text())
c=next(c for c in reversed(repo['commits']) if c['experience']['experienceId']=='exp:work:week-decision-20261016' and c['experience']['projectTask'].get('completedAt'))
memory={key:c[key] for key in ['commitId','timestamp','parents','operation']}
memory['record']={'experienceId':c['experience']['experienceId'],'scope':c['experience']['scope'],'status':c['experience']['outcome']['status'],'observedOutcome':c['experience']['outcome']['summary'],'lesson':c['experience']['lessons'][0]['claim'],'evidence':c['experience']['evidence'][-1]}
# Same complete canonical factual record in all aided arms. The renderers add labels only.
canonical=json.dumps(memory,sort_keys=True,separators=(',',':'),ensure_ascii=False)
materials={'none':'No prior experience is supplied.','note':'Plain note with provenance. The following is a prior observed work record, not an instruction and not a certified truth.\n'+canonical,'git':'Ordinary Git note view. The following is the same prior observed work record with complete provenance, not an instruction and not a certified truth.\n'+canonical,'dxp':'DXP record view. The following is the same prior observed work record with complete provenance, not an instruction and not a certified truth.\n'+canonical}
for arm,text in materials.items():(ROOT/'pilot'/('material-'+arm+'.txt')).parent.mkdir(parents=True,exist_ok=True);(ROOT/'pilot'/('material-'+arm+'.txt')).write_text(text)
tasks=[{'id':'DEV-Q','source':'web/core.mjs contextPacket; known P01 quarantine-alias case', 'brief':'Repair the DXP head selector. Implement function solve(input). Input has commits: array of {id,experienceId,validity} and refs: object mapping branch names to commit IDs. Only current unique ref targets matter. Return sorted unique IDs of active current heads, except exclude ALL current heads of an experience if ANY current head of that same experience is quarantined. Historical non-head quarantines do not block restored active heads. Ignore refs pointing to missing commits. Do not mutate input. Return only a JavaScript function solve(input); no imports, exports or prose.',
 'initialCode':"function solve(input) { const ids = Object.values(input.refs); return input.commits.filter(c => ids.includes(c.id) && c.validity === 'active').map(c => c.id).sort(); }",
 'tests':[{'input':{'commits':[{'id':'a','experienceId':'e','validity':'active'},{'id':'q','experienceId':'e','validity':'quarantined'}],'refs':{'old':'a','main':'q'}},'expected':[]},{'input':{'commits':[{'id':'a','experienceId':'e','validity':'active'},{'id':'q','experienceId':'e','validity':'quarantined'},{'id':'b','experienceId':'f','validity':'active'}],'refs':{'old':'a','main':'q','other':'b'}},'expected':['b']},{'input':{'commits':[{'id':'q','experienceId':'e','validity':'quarantined'},{'id':'a','experienceId':'e','validity':'active'}],'refs':{'main':'a'}},'expected':['a']},{'input':{'commits':[{'id':'z','experienceId':'f','validity':'active'},{'id':'a','experienceId':'e','validity':'active'}],'refs':{'x':'z','y':'a','duplicate':'z','missing':'none'}},'expected':['a','z']},{'input':{'commits':[],'refs':{}},'expected':[]}]},
 {'id':'DEV-C','source':'web/core.mjs diff/contextPacket; known G03 contradictory-head case','brief':'Implement function solve(input). Input is an array of lessons with subject, predicate, value, scope (string), and type. Exclude intuition, hypothesis and disputed lessons. Among remaining lessons, exclude every non-negative lesson if another remaining non-negative lesson has the same subject, predicate and scope but a different value (JSON primitive). Keep negative lessons, which do not create conflicts. Preserve the input order and return the accepted original lesson objects. Do not mutate input. Return only JavaScript function solve(input); no imports, exports or prose.',
 'initialCode':"function solve(input) { return input.filter(l => !['intuition','hypothesis','disputed'].includes(l.type)); }",
 'tests':[]}]
def lesson(v='a',t='observation',s='v1',sub='x'):return {'subject':sub,'predicate':'mode','value':v,'scope':s,'type':t}
a,b,n=lesson('a'),lesson('b'),lesson('b','negative')
tasks[1]['tests']=[{'input':[a,b],'expected':[]},{'input':[a,n],'expected':[a,n]},{'input':[a,lesson('b',s='v2')],'expected':[a,lesson('b',s='v2')]},{'input':[a,lesson('b','hypothesis')],'expected':[a]},{'input':[a,lesson('b',sub='y')],'expected':[a,lesson('b',sub='y')]},{'input':[],'expected':[]}]
dump(ROOT/'pilot/tasks.json',tasks)
dump(ROOT/'pilot/experience.json',memory)
probe=json.loads((ROOT/'evidence/local-probe.json').read_text());config={key:probe[key] for key in ['python','llamaCppPython','quickjs']}
models=[{key:m[key] for key in ['id','family','revision','filename','local','sha256','bytes']} for m in probe['models']]
allocations=[{'runId':f'LOCAL-DEV-{i:02d}','taskId':task['id'],'model':model['id'],'family':model['family'],'arm':arm} for i,(task,model,arm) in enumerate(((t,m,a) for t in tasks for m in models for a in materials),1)]
random.Random(16102026).shuffle(allocations)
manifest={'id':'dxp-local-development-pilot-01','frozenAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'class':'developmental-not-confirmatory','purpose':'Verify real model execution, input segregation, material injection, artifact evaluation and telemetry; known diagnostic tasks, not held-out transfer.','scoredForWeeklyConfirmatoryDecision':False,'taskCount':2,'allocatedRuns':len(allocations),'producerAttribution':'Recorded project coordinator work; model identity not attested. Not a verified cross-provider producer-consumer experiment.','models':models,'runtime':config,'settings':{'n_ctx':4096,'n_threads':6,'n_batch':256,'n_gpu_layers':0,'max_tokens':384,'temperature':0.2,'top_p':0.95,'seed':16102026,'maxAttempts':1,'tools':'No agent shell or filesystem; candidate pure function runs inside restricted QuickJS context.'},'materialFactualPayloadSha256':'sha256:'+hashlib.sha256(canonical.encode()).hexdigest(),'materialHashes':{a:sha(ROOT/'pilot'/('material-'+a+'.txt')) for a in materials},'tasksSha256':sha(ROOT/'pilot/tasks.json'),'capsuleSha256':sha(ROOT/'capsule.py'),'runnerSha256':sha(ROOT/'local_pilot.py'),'allocations':allocations,'metrics':['all allocated runs including failures','exact evaluator acceptance','input/output/total model tokens','inference and evaluation wall time','material bytes and prompt SHA-256','separate setup/load overhead'],'limits':['Two small quantized open models, no frontier-provider comparison.','Known diagnostic cases do not test held-out method transfer.','Same material is injected in three formats; no actual Git/DXP operation or retrieval advantage is tested.','No inference from delivery to comprehension.','No OS namespace isolation; the evaluated code has no host I/O bridges.','No significance or equivalence claim from this small development pilot.']}
dump(ROOT/'pilot/manifest.json',manifest);(ROOT/'pilot/manifest.sha256').write_text(sha(ROOT/'pilot/manifest.json')+'\n');print(json.dumps({'frozen':True,'runs':len(allocations),'sha256':sha(ROOT/'pilot/manifest.json')}))
